const maps: Record<Exclude<InterfaceLanguage, 'en'>, PhraseMap> = {
  uk: { ...uk, ...supplementalUk, ...catalogUk, ...interfaceUk, ...errorUk, ...serverErrorUk },
  ru: { ...ru, ...supplementalRu, ...catalogRu, ...interfaceRu, ...errorRu, ...serverErrorRu },
};

const inflect = (
  language: Exclude<InterfaceLanguage, 'en'>,
  value: number,
  uk: [string, string, string],
  ru: [string, string, string],
) => {
  const category = new Intl.PluralRules(language === 'uk' ? 'uk-UA' : 'ru-RU').select(value);
  const index = category === 'one' ? 0 : category === 'few' ? 1 : 2;
  return (language === 'uk' ? uk : ru)[index];
};

const dynamic = (language: Exclude<InterfaceLanguage, 'en'>, value: string) => {
  const greeting = value.match(/^Good (morning|afternoon|evening), (.+)\.$/);
  if (greeting) {
    const prefix = language === 'uk'
      ? ({ morning: 'Доброго ранку', afternoon: 'Добрий день', evening: 'Добрий вечір' } as const)[greeting[1] as 'morning']
      : ({ morning: 'Доброе утро', afternoon: 'Добрый день', evening: 'Добрый вечер' } as const)[greeting[1] as 'morning'];
    return `${prefix}, ${greeting[2]}.`;
  }
  const available = value.match(/^(\d+) (White|Yellow|Blue) Sparks available$/);
  if (available) return language === 'uk' ? `Доступно: ${available[1]} ${available[2]} Sparks` : `Доступно: ${available[1]} ${available[2]} Sparks`;
  const remaining = value.match(/^(\d+) remaining$/);
  if (remaining) return language === 'uk' ? `Залишилося: ${remaining[1]}` : `Осталось: ${remaining[1]}`;
  const genericAvailable = value.match(/^(\d+) available$/);
  if (genericAvailable) return language === 'uk' ? `Доступно: ${genericAvailable[1]}` : `Доступно: ${genericAvailable[1]}`;
  const nominationsAvailable = value.match(/^(\d+) nominations? available$/);
  if (nominationsAvailable) {
    const count = Number(nominationsAvailable[1]);
    const noun = inflect(language, count, ['номінація', 'номінації', 'номінацій'], ['номинация', 'номинации', 'номинаций']);
    return language === 'uk' ? `Доступно: ${count} ${noun}` : `Доступно: ${count} ${noun}`;
  }
  const gpmScope = value.match(/^(\d+) active (?:Coordinator or registrar|Coordinators or registrars) under your control\. One White award is available for every group of up to (\d+)\.$/);
  if (gpmScope) return language === 'uk'
    ? `Під вашим керуванням активних координаторів або реєстраторів: ${gpmScope[1]}. Одна нагорода White доступна на кожну групу до ${gpmScope[2]} осіб.`
    : `Под вашим управлением активных координаторов или регистраторов: ${gpmScope[1]}. Одна награда White доступна на каждую группу до ${gpmScope[2]} человек.`;
  const allocation = value.match(/^(Q\d \d{4}) allocation$/);
  if (allocation) return language === 'uk' ? `Квота ${allocation[1]}` : `Квота ${allocation[1]}`;
  const activeCategories = value.match(/^(\d+) active categories$/);
  if (activeCategories) {
    const count = Number(activeCategories[1]);
    const adjective = inflect(language, count, ['активна', 'активні', 'активних'], ['активная', 'активные', 'активных']);
    const noun = inflect(language, count, ['категорія', 'категорії', 'категорій'], ['категория', 'категории', 'категорий']);
    return `${count} ${adjective} ${noun}`;
  }
  const categoryAllowance = value.match(/^(\d+) (Yellow|Blue) · one category per employee per quarter$/);
  if (categoryAllowance) return language === 'uk'
    ? `${categoryAllowance[1]} ${categoryAllowance[2]} · одна категорія на працівника за квартал`
    : `${categoryAllowance[1]} ${categoryAllowance[2]} · одна категория на сотрудника за квартал`;
  const needMore = value.match(/^You need (\d+) more (White|Yellow|Blue) Sparks for this conversion\.$/);
  if (needMore) return language === 'uk'
    ? `Для цієї конвертації потрібно ще ${needMore[1]} ${needMore[2]} Sparks.`
    : `Для этой конвертации нужно ещё ${needMore[1]} ${needMore[2]} Sparks.`;
  const shopNeedMore = value.match(/^You need ([\d\s,.]+) more (White|Yellow|Blue) Sparks?\. Earn or convert Sparks to complete this purchase\.$/);
  if (shopNeedMore) return language === 'uk'
    ? `Потрібно ще ${shopNeedMore[1]} ${shopNeedMore[2]} Sparks. Заробіть або конвертуйте Sparks, щоб завершити покупку.`
    : `Нужно ещё ${shopNeedMore[1]} ${shopNeedMore[2]} Sparks. Заработайте или конвертируйте Sparks, чтобы завершить покупку.`;
  const balanceCoverage = value.match(/^Your balance covers (\d+) percent of the item price$/);
  if (balanceCoverage) return language === 'uk'
    ? `Ваш баланс покриває ${balanceCoverage[1]}% вартості товару`
    : `Ваш баланс покрывает ${balanceCoverage[1]}% стоимости товара`;
  const artwork = value.match(/^(.+) reward artwork$/);
  if (artwork) return language === 'uk' ? `Зображення нагороди «${artwork[1]}»` : `Изображение награды «${artwork[1]}»`;
  const fillEmail = value.match(/^Fill (.+)'s email$/);
  if (fillEmail) return language === 'uk' ? `Вставити адресу ${fillEmail[1]}` : `Вставить адрес ${fillEmail[1]}`;
  const editItem = value.match(/^Edit (.+)$/);
  if (editItem) return language === 'uk' ? `Редагувати: ${editItem[1]}` : `Редактировать: ${editItem[1]}`;
  const recognitionAction = value.match(/^(Hide|Show) recognition action for (.+)$/);
  if (recognitionAction) {
    const verb = recognitionAction[1] === 'Hide'
      ? (language === 'uk' ? 'Сховати' : 'Скрыть')
      : (language === 'uk' ? 'Показати' : 'Показать');
    return `${verb} ${language === 'uk' ? 'дію визнання для' : 'действие признания для'} ${recognitionAction[2]}`;
  }
  const passwordRequirement = value.match(/^(Met|Not met): (8 or more characters|upper and lowercase letters|at least one number)$/);
  if (passwordRequirement) {
    const state = passwordRequirement[1] === 'Met'
      ? (language === 'uk' ? 'Виконано' : 'Выполнено')
      : (language === 'uk' ? 'Не виконано' : 'Не выполнено');
    const requirement = ({
      '8 or more characters': language === 'uk' ? 'щонайменше 8 символів' : 'не менее 8 символов',
      'upper and lowercase letters': language === 'uk' ? 'великі та малі літери' : 'прописные и строчные буквы',
      'at least one number': language === 'uk' ? 'щонайменше одна цифра' : 'не менее одной цифры',
    } as Record<string, string>)[passwordRequirement[2]];
    return `${state}: ${requirement}`;
  }
  const roleWorkspace = value.match(/^(Employee|Coordinator|GPM|Head|Top Management|Administrator) workspace$/);
  if (roleWorkspace) {
    const roles: Record<string, [string, string]> = {
      Employee: ['Простір працівника', 'Пространство сотрудника'], Coordinator: ['Простір координатора', 'Пространство координатора'],
      GPM: ['Простір GPM', 'Пространство GPM'], Head: ['Простір керівника', 'Пространство руководителя'],
      'Top Management': ['Простір топменеджменту', 'Пространство топ-менеджмента'], Administrator: ['Простір адміністратора', 'Пространство администратора'],
    };
    return roles[roleWorkspace[1]][language === 'uk' ? 0 : 1];
  }
  const reportExported = value.match(/^Report for (\d{4}-\d{2}) exported: (\d+) requests? included\.$/);
  if (reportExported) return language === 'uk'
    ? `Звіт за ${reportExported[1]} експортовано. Додано запитів: ${reportExported[2]}.`
    : `Отчёт за ${reportExported[1]} экспортирован. Добавлено запросов: ${reportExported[2]}.`;
  const referencesSaved = value.match(/^(.+) saved\. Future forms now use the updated reference data\.$/);
  if (referencesSaved) return language === 'uk'
    ? `«${referencesSaved[1]}» збережено. У нових формах використовуються оновлені дані.`
    : `«${referencesSaved[1]}» сохранено. В новых формах используются обновлённые данные.`;
  const categorySaved = value.match(/^(.+) saved\. Future rewards use the new category version\.$/);
  if (categorySaved) return language === 'uk'
    ? `«${categorySaved[1]}» збережено. Для майбутніх нагород використовується нова версія категорії.`
    : `«${categorySaved[1]}» сохранено. Для будущих наград используется новая версия категории.`;
  const referenceDeleted = value.match(/^(.+) was deleted from Employee Directory\.$/);
  if (referenceDeleted) return language === 'uk' ? `«${referenceDeleted[1]}» видалено з довідника працівників.` : `«${referenceDeleted[1]}» удалено из справочника сотрудников.`;
  const canSignIn = value.match(/^(.+) can now sign in\.$/);
  if (canSignIn) return language === 'uk' ? `${canSignIn[1]} тепер може ввійти.` : `${canSignIn[1]} теперь может войти.`;
  const wasRejected = value.match(/^(.+) was rejected\.$/);
  if (wasRejected) return language === 'uk' ? `Запит ${wasRejected[1]} відхилено.` : `Запрос ${wasRejected[1]} отклонён.`;
  const awardedBy = value.match(/^Awarded by (.+)$/);
  if (awardedBy) return language === 'uk' ? `Нагородив: ${awardedBy[1]}` : `Наградил: ${awardedBy[1]}`;
  const seeMore = value.match(/^See more \((\d+)\)$/);
  if (seeMore) return language === 'uk' ? `Показати ще (${seeMore[1]})` : `Показать ещё (${seeMore[1]})`;
  const showMoreAchievements = value.match(/^Show more achievements \((\d+)\)$/);
  if (showMoreAchievements) return language === 'uk' ? `Показати більше досягнень (${showMoreAchievements[1]})` : `Показать больше достижений (${showMoreAchievements[1]})`;
  const gateUntil = value.match(/^Gate until (.+)$/);
  if (gateUntil) return language === 'uk' ? `Обмеження до ${gateUntil[1]}` : `Ограничение до ${gateUntil[1]}`;
  const monthlyAccounting = value.match(/^Monthly accounting · (.+)$/);
  if (monthlyAccounting) return language === 'uk' ? `Щомісячна бухгалтерія · ${monthlyAccounting[1]}` : `Ежемесячная бухгалтерия · ${monthlyAccounting[1]}`;
  const displayDate = value.match(/^(MONDAY|TUESDAY|WEDNESDAY|THURSDAY|FRIDAY|SATURDAY|SUNDAY) (\d{1,2}) (JANUARY|FEBRUARY|MARCH|APRIL|MAY|JUNE|JULY|AUGUST|SEPTEMBER|OCTOBER|NOVEMBER|DECEMBER)$/i);
  if (displayDate) {
    const weekdays = language === 'uk'
      ? ['ПОНЕДІЛОК', 'ВІВТОРОК', 'СЕРЕДА', 'ЧЕТВЕР', 'П’ЯТНИЦЯ', 'СУБОТА', 'НЕДІЛЯ']
      : ['ПОНЕДЕЛЬНИК', 'ВТОРНИК', 'СРЕДА', 'ЧЕТВЕРГ', 'ПЯТНИЦА', 'СУББОТА', 'ВОСКРЕСЕНЬЕ'];
    const months = language === 'uk'
      ? ['СІЧНЯ', 'ЛЮТОГО', 'БЕРЕЗНЯ', 'КВІТНЯ', 'ТРАВНЯ', 'ЧЕРВНЯ', 'ЛИПНЯ', 'СЕРПНЯ', 'ВЕРЕСНЯ', 'ЖОВТНЯ', 'ЛИСТОПАДА', 'ГРУДНЯ']
      : ['ЯНВАРЯ', 'ФЕВРАЛЯ', 'МАРТА', 'АПРЕЛЯ', 'МАЯ', 'ИЮНЯ', 'ИЮЛЯ', 'АВГУСТА', 'СЕНТЯБРЯ', 'ОКТЯБРЯ', 'НОЯБРЯ', 'ДЕКАБРЯ'];
    const dayIndex = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'].indexOf(displayDate[1].toUpperCase());
    const monthIndex = ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'].indexOf(displayDate[3].toUpperCase());
    return `${weekdays[dayIndex]} ${displayDate[2]} ${months[monthIndex]}`;
  }
  const shortDate = value.match(/^(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(,? .*)?$/);
  if (shortDate) {
    const monthIndex = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].indexOf(shortDate[2]);
    const months = language === 'uk'
      ? ['січ.', 'лют.', 'бер.', 'квіт.', 'трав.', 'черв.', 'лип.', 'серп.', 'вер.', 'жовт.', 'лист.', 'груд.']
      : ['янв.', 'февр.', 'мар.', 'апр.', 'мая', 'июн.', 'июл.', 'авг.', 'сент.', 'окт.', 'нояб.', 'дек.'];
    return `${shortDate[1]} ${months[monthIndex]}${shortDate[3] ?? ''}`;
  }
  return value;
};

export function localizeContent(language: InterfaceLanguage, value: string) {
  if (language === 'en') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;
  const translated = maps[language][trimmed] ?? dynamic(language, trimmed);
  if (translated === trimmed) return value;
  return value.replace(trimmed, translated);
}
